const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

/* ── root page scenarios ── */

Given('the root index.html is parsed', function () {
  const { Window } = require('happy-dom');
  var rootWin = new Window({ url: 'http://localhost:3000/' });
  var htmlPath = path.join(__dirname, '..', '..', 'index.html');
  var html = fs.readFileSync(htmlPath, 'utf-8');
  rootWin.document.body.innerHTML = html;
  this.rootDocument = rootWin.document;
  this.rootWindow = rootWin;
});

Then('the root page contains a {string} element', function (selector) {
  var el = this.rootDocument.querySelector(selector);
  assert.ok(el, 'Root page should contain a "' + selector + '" element');
});

Then('the root page contains a {string} input', function (selector) {
  var el = this.rootDocument.querySelector(selector);
  assert.ok(el, 'Root page should contain a "' + selector + '" input');
  assert.strictEqual(el.tagName.toLowerCase(), 'input',
    '"' + selector + '" should be an input element');
});

Then('the root page contains a {string} checkbox', function (selector) {
  var el = this.rootDocument.querySelector(selector);
  assert.ok(el, 'Root page should contain a "' + selector + '" element');
  assert.strictEqual(el.type, 'checkbox',
    '"' + selector + '" should be a checkbox');
});

Then('the root page loads a script with src {string}', function (src) {
  var scripts = this.rootDocument.querySelectorAll('script[src]');
  var found = false;
  scripts.forEach(function (s) {
    if (s.getAttribute('src') === src) found = true;
  });
  assert.ok(found, 'Root page should load a script with src="' + src + '"');
});

/* ── navigation and page lifecycle ── */

Given('the page is open', function () {
  /* page loaded in World constructor */
});

When('the page loads', function () {
  /* page loaded in World constructor */
});

When('the page is reloaded', function () {
  const { Window } = require('happy-dom');
  const fs = require('fs');
  const path = require('path');

  /* preserve localStorage and hash across reload */
  const storedKeys = {};
  for (let i = 0; i < this.window.localStorage.length; i++) {
    const key = this.window.localStorage.key(i);
    storedKeys[key] = this.window.localStorage.getItem(key);
  }
  const prevHash = this.window.location.hash;

  this.window = new Window({ url: 'http://localhost:3000/' });
  this.document = this.window.document;

  /* restore localStorage and hash */
  Object.keys(storedKeys).forEach(function (key) {
    this.window.localStorage.setItem(key, storedKeys[key]);
  }.bind(this));
  if (prevHash) this.window.location.hash = prevHash;

  const htmlPath = path.join(__dirname, '..', '..', 'src', 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf-8');
  this.document.body.innerHTML = html;

  const appPath = path.join(__dirname, '..', '..', 'src', 'app.js');
  const appCode = fs.readFileSync(appPath, 'utf-8');
  this.window.eval(appCode);

  this.app = this.window.app;
  this._editingTodoId = null;
});

When('I navigate to {string}', function (hash) {
  this.window.location.hash = hash.replace(/^#/, '');
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

/* ── todo setup ── */

Given('the following todos exist:', function (dataTable) {
  dataTable.rows().forEach(function (row) {
    this.app.addTodo(row[0]);
    if (row[1] === 'true') {
      var todo = this.app.todos.find(function (t) { return t.title === row[0]; });
      if (todo) {
        todo.completed = true;
        this.app.save();
      }
    }
  }.bind(this));
  this.app.render();
});

Given('the todo {string} exists', function (title) {
  this.app.addTodo(title);
});

Given('the completed todo {string} exists', function (title) {
  this.app.addTodo(title);
  var todo = this.app.todos.find(function (t) { return t.title === title; });
  if (todo) {
    todo.completed = true;
    this.app.save();
    this.app.render();
  }
});

Given('the todo {string} is in editing mode', function (title) {
  this.app.addTodo(title);
  var todo = this.app.todos.find(function (t) { return t.title === title; });
  if (todo) {
    this.app.editingId = todo.id;
    this.app._editCancelled = false;
    this.app.render();
    this._editingTodoId = todo.id;
  }
});

Given('the page has stored two todos in localStorage', function () {
  this.window.localStorage.setItem('todos-vanilla-js', JSON.stringify([
    { id: 1, title: 'First todo', completed: false },
    { id: 2, title: 'Second todo', completed: true }
  ]));
});

/* ── input actions ── */

When('I type {string} in the new todo input', function (text) {
  var input = this.document.querySelector('.new-todo');
  input.focus();
  input.value = text;
});

When('I press Enter', function () {
  var el = this.document.activeElement;
  if (el && el.classList.contains('new-todo')) {
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  } else if (el && el.classList.contains('edit')) {
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }
});

When('I press Escape', function () {
  var el = this.document.activeElement;
  if (el && el.classList.contains('edit')) {
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  }
});

/* ── toggle actions ── */

When('I check the toggle-all checkbox', function () {
  var cb = this.document.querySelector('.toggle-all');
  cb.checked = !cb.checked;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I complete the todo {string}', function (title) {
  var li = this.findTodoLi(title);
  var toggle = li.querySelector('.toggle');
  toggle.click();
});

When('I click the toggle checkbox for {string}', function (title) {
  var li = this.findTodoLi(title);
  var toggle = li.querySelector('.toggle');
  toggle.click();
});

/* ── destroy actions ── */

When('I click the destroy button for {string}', function (title) {
  var li = this.findTodoLi(title);
  var destroy = li.querySelector('.destroy');
  destroy.click();
});

/* ── editing actions ── */

When('I double-click the label of {string}', function (title) {
  var li = this.findTodoLi(title);
  var label = li.querySelector('label');
  var todo = this.app.todos.find(function (t) { return t.title === title; });
  if (todo) this._editingTodoId = todo.id;
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I clear the edit input', function () {
  var edit = this.document.querySelector('.todo-list .edit');
  if (edit) { edit.focus(); edit.value = ''; }
});

When('I clear the edit input and type {string}', function (text) {
  var edit = this.document.querySelector('.todo-list .edit');
  if (edit) { edit.focus(); edit.value = text; }
});

When('I blur the edit input', function () {
  var edit = this.document.querySelector('.todo-list .edit');
  if (edit) { edit.focus(); edit.blur(); }
});

When('I hover over the todo {string}', function (title) {
  /* hover is visual; no DOM state change needed */
});

/* ── clear completed ── */

When('I click the clear completed button', function () {
  this.document.querySelector('.clear-completed').click();
});

/* ── assertions: visibility ── */

Then('the main section is hidden', function () {
  var main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none', 'main section should be hidden');
