const puppeteer = require('puppeteer');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = __dirname;

// Simple static file server
function createServer() {
  return http.createServer((req, res) => {
    let filePath = path.join(ROOT, req.url === '/' ? 'index.html' : req.url);
    filePath = decodeURI(filePath);
    const ext = path.extname(filePath);
    const types = { '.html': 'text/html', '.js': 'application/javascript', '.css': 'text/css' };
    fs.readFile(filePath, (err, data) => {
      if (err) { res.writeHead(404); res.end('Not found'); return; }
      res.writeHead(200, { 'Content-Type': types[ext] || 'text/plain' });
      res.end(data);
    });
  });
}

async function main() {
  const server = createServer();
  await new Promise(r => server.listen(0, r));
  const port = server.address().port;
  console.log('Server on port', port);

  const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
  const page = await browser.newPage();

  // Capture console messages
  page.on('console', msg => console.log('BROWSER:', msg.text()));

  await page.goto(`http://localhost:${port}/`);

  // Add helper to observe DOM mutations
  await page.evaluate(() => {
    window.__mutations = [];
    const obs = new MutationObserver(mutations => {
      mutations.forEach(m => {
        if (m.type === 'childList' && m.removedNodes.length > 0) {
          m.removedNodes.forEach(n => {
            if (n.tagName === 'LI' && n.closest && n.closest('.todo-list')) {
              window.__mutations.push({ type: 'li-removed', id: n.dataset?.id, time: Date.now() });
            }
          });
        }
        if (m.type === 'childList' && m.addedNodes.length > 0) {
          m.addedNodes.forEach(n => {
            if (n.tagName === 'LI' && n.dataset?.id) {
              window.__mutations.push({ type: 'li-added', id: n.dataset.id, time: Date.now() });
            }
          });
        }
      });
    });
    obs.observe(document.querySelector('.todo-list'), { childList: true, subtree: true });
  });

