  const firstToggle = await page.$('.todo-list li:first-child .toggle');

  console.log('Before click - first li attached:', await page.evaluate(el => document.contains(el), firstLi));

  // Click the toggle (this is what Cypress check() does)
  await firstToggle.click();

  // Wait a bit for any async effects
  await new Promise(r => setTimeout(r, 100));

  // Check state after clicking
  let state2 = await page.evaluate(() => {
    const lis = document.querySelectorAll('.todo-list li');
