  let modelState = await page.evaluate(() => {
    return window.app.todos.map(t => ({ id: t.id, title: t.title, completed: t.completed }));
  });
  console.log('Model state:', JSON.stringify(modelState, null, 2));

  // Check mutations
  let mutations = await page.evaluate(() => window.__mutations);
  console.log('DOM Mutations:', JSON.stringify(mutations, null, 2));

  // Now simulate clicking the toggle AGAIN (un-check, like uncheck())
  console.log('\n=== Simulating Cypress uncheck() on first toggle ===');

  const firstToggle2 = await page.$('.todo-list li:first-child .toggle');
  console.log('Second check - found toggle:', !!firstToggle2);

  await firstToggle2.click();
  await new Promise(r => setTimeout(r, 100));

  let state3 = await page.evaluate(() => {
    const lis = document.querySelectorAll('.todo-list li');
    return Array.from(lis).map(li => ({
      id: li.dataset.id,
      checked: li.querySelector('.toggle').checked,
      hasCompleted: li.classList.contains('completed')
    }));
