// Test 1: Simulate what a REAL browser does when clicking a checkbox
// In a real browser, element.click():
//   1. Dispatches a click event
//   2. If not prevented, toggles the checkbox checked state
//   3. If state changed, dispatches a change event
function realBrowserClick(element, win) {
  // Step 1: Dispatch click event
  const clickEvent = new win.MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    view: win
  });
  const notPrevented = element.dispatchEvent(clickEvent);

  // Step 2: If click not prevented, toggle checkbox state (browser default)
  if (notPrevented && element.type === 'checkbox') {
    const oldChecked = element.checked;
    element.checked = !oldChecked;

    // Step 3: If state changed, dispatch change event
    if (element.checked !== oldChecked) {
      element.dispatchEvent(new win.Event('change', { bubbles: true }));
    }
  }
}

