console.log('\n=== Test 6: Simulating Cypress check() - dispatchEvent click sequence ===');
{
  const { win, doc, app } = setupApp();
  app.addTodo('cypress test item');

  const toggle = doc.querySelector('.todo-list li .toggle');
  const li = doc.querySelector('.todo-list li');

  // Cypress check() fires: pointerdown, mousedown, focus, pointerup, mouseup, click
  // In a real browser, the click event triggers checkbox toggle + change event
  // Let's simulate the click dispatch like Cypress does:
  const clickEvent = new win.MouseEvent('click', {
    bubbles: true, cancelable: true, view: win
  });
  toggle.dispatchEvent(clickEvent);

  // In happy-dom, dispatchEvent already toggled and fired change
  assert(toggle.checked === true, 'cypress: toggle checked after dispatched click');
  assert(li.classList.contains('completed'), 'cypress: li has completed class');
  assert(app.todos[0].completed === true, 'cypress: model completed');
  assert(doc.contains(li), 'cypress: li still attached to DOM');
  assert(doc.contains(toggle), 'cypress: toggle still attached to DOM');

  // Now simulate click again (for uncheck)
  const clickEvent2 = new win.MouseEvent('click', {
    bubbles: true, cancelable: true, view: win
  });
  toggle.dispatchEvent(clickEvent2);

  assert(toggle.checked === false, 'cypress uncheck: toggle unchecked');
  assert(!li.classList.contains('completed'), 'cypress uncheck: no completed class');
  assert(app.todos[0].completed === false, 'cypress uncheck: model active');
}

